  var NEWQ = [
    ['t1', 10, ['Free List [0, 10] → [20, 10]; belegt ist nur [10, 10]. Dieser Block wird **mit Coalescing** freigegeben. Wie sieht die Liste danach aus?', ['[0, 30]', '[10, 10] → [0, 10] → [20, 10]', '[0, 20] → [20, 10]', '[0, 10] → [20, 10]'], 'Alle drei Stücke liegen nebeneinander.', 3]],
    ['t1', 13, ['Free List [0, 10] → [20, 10]. malloc(4) wird aus dem **ersten** Stück bedient (ohne Header). Was bekommt der Aufrufer, und wie lautet der Eintrag danach?', ['Adresse 0, Eintrag [4, 6]', 'Adresse 4, Eintrag [0, 6]', 'Adresse 0, Eintrag [0, 6]', 'Adresse 20, Eintrag [24, 6]'], 'Splitting: vorne abgeben, Rest bleibt in der Liste.', 2]],
    ['t2', 9, ['Ein Heap hat 8192 Bytes, der Listenknoten 8 Bytes, jeder Header 8 Bytes. Nach zwei Anfragen à 200 Bytes: Wie groß ist das freie Stück noch?', ['7768', '7784', '7776', '7976'], '8184 − 2 · 208.', 2]],
    ['t4', 9, ['Ein binärer Buddy-Allokator verwaltet 64 KB. Eine Anfrage über 20 KB kommt. Wie viel interne Fragmentierung entsteht?', ['12 KB', '0 KB', '4 KB', '44 KB'], 'Es wird auf 32 KB aufgerundet.', 2]]
  ];
  NEWQ.forEach(function (x) { x[2][5] = 'n2'; T(x[0]).q[x[1]] = x[2]; });

  /* ---------- Eingabefragen ---------- */
  var add = function (tid, g) { (T(tid).gen = T(tid).gen || []).push(g); };
  add('t1', { n: 3, f: function (r) {
    var a = u.ri(r, 1, 30) * 4, len = u.ri(r, 8, 40), k = u.ri(r, 1, len - 1), v = a + k, wr = {};
    wr[a] = 'Die vorderen ' + k + ' Bytes gehen an den Aufrufer – der freie Rest beginnt dahinter.'; wr[len - k] = 'Das ist die neue Länge, nicht die Startadresse.'; wr[a + len] = 'Das ist das Ende des Stücks.'; delete wr[v];
    return { q: 'Free-List-Eintrag **[Adresse ' + a + ', Länge ' + len + ']**. malloc(' + k + ') wird daraus bedient (ohne Header). Bei welcher **Adresse** beginnt der freie Rest?', num: v, unit: '', hint: 'Ganze Zahl (Adresse in Bytes)', e: '**Rechenweg:** Splitting gibt die ersten ' + k + ' Bytes (ab ' + a + ') an den Aufrufer.\nDer Rest beginnt bei ' + a + ' + ' + k + ' = **' + v + '** und ist noch ' + (len - k) + ' Bytes lang.', s: 2, wr: wr };
  } });
  add('t2', { n: 3, f: function (r) {
    var hs = u.pick(r, [8, 16]), ptr = u.ri(r, 200, 900) * 8, v = ptr - hs, wr = {};
    wr[ptr + hs] = 'Der Header liegt **vor** dem Bereich, nicht dahinter.'; wr[ptr] = 'Das ist der Zeiger des Programms – der Header liegt davor.';
    return { q: 'free(ptr) wird mit **ptr = ' + ptr + '** aufgerufen. Der Header ist **' + hs + ' Bytes** groß. Bei welcher Adresse beginnt der Header?', num: v, unit: '', hint: 'Ganze Zahl (Adresse in Bytes)', e: '**Rechenweg:** Der Header liegt direkt vor dem Bereich: hptr = ptr − sizeof(header_t).\n' + ptr + ' − ' + hs + ' = **' + v + '**.', s: 0, wr: wr };
  } });
  add('t2', { n: 3, f: function (r) {
    var H = u.pick(r, [4096, 8192]), n = u.ri(r, 1, 4), sz = u.pick(r, [32, 50, 64, 100, 128, 200]), v = H - 8 - n * (sz + 8), wr = {};
    wr[H - 8 - n * sz] = 'Jede Anfrage braucht zusätzlich 8 Bytes Header.'; wr[H - n * (sz + 8)] = 'Der Listenknoten (8 Bytes) belegt am Anfang Platz.';
    return { q: 'Heap mit **' + H + ' Bytes**, Listenknoten 8 Bytes, Header 8 Bytes. Es kommen **' + n + '× malloc(' + sz + ')** aus dem einen freien Stück. Wie groß ist das freie Stück danach (Wert von size)?', num: v, unit: 'Bytes', hint: 'Ganze Zahl in Bytes', e: '**Rechenweg:** Anfangs: ' + H + ' − 8 = ' + (H - 8) + ' Bytes.\nJede Anfrage kostet ' + sz + ' + 8 = ' + (sz + 8) + ' Bytes.\n' + (H - 8) + ' − ' + n + ' · ' + (sz + 8) + ' = **' + v + '**.', s: 2, wr: wr };
  } });
  add('t3', { n: 3, f: function (r) {
    var L = [u.ri(r, 2, 9) * 5, u.ri(r, 2, 9) * 5, u.ri(r, 2, 9) * 5], req = u.ri(r, 2, 7) * 5, st = u.pick(r, ['best', 'worst', 'first']);
    var ok = L.filter(function (x) { return x >= req; }); if (!ok.length) { L[1] = req + 10; ok = [L[1]]; }
    var pick = st === 'best' ? Math.min.apply(null, ok) : st === 'worst' ? Math.max.apply(null, ok) : L.filter(function (x) { return x >= req; })[0], v = pick - req, wr = {}, nm = { best: 'Best Fit', worst: 'Worst Fit', first: 'First Fit' }[st];
    var bf = Math.min.apply(null, ok) - req, wf = Math.max.apply(null, ok) - req, ff = L.filter(function (x) { return x >= req; })[0] - req;
    if (bf !== v) wr[bf] = 'Das wäre der Rest bei Best Fit.'; if (wf !== v) wr[wf] = 'Das wäre der Rest bei Worst Fit.'; if (ff !== v) wr[ff] = 'Das wäre der Rest bei First Fit.';
    return { q: 'Free List (in dieser Reihenfolge): **' + L.join(' → ') + '**. Anfrage über **' + req + '** Bytes mit **' + nm + '**. Wie groß ist der Rest des gewählten Stücks?', num: v, unit: 'Bytes', hint: 'Ganze Zahl in Bytes (0, wenn es genau passt)', e: '**Rechenweg:** Passend (≥ ' + req + '): ' + ok.join(', ') + '.\n' + nm + ' wählt ' + pick + ' → Rest ' + pick + ' − ' + req + ' = **' + v + '**.', s: st === 'best' ? 0 : st === 'worst' ? 1 : 2, wr: wr };
  } });
  add('t4', { n: 3, f: function (r) {
    var req = u.ri(r, 3, 60), b = 1; while (b < req) b *= 2; var wr = {};
    wr[req] = 'Der Buddy-Allokator vergibt nur Zweierpotenzen.'; if (b / 2 >= 1) wr[b / 2] = b / 2 + ' KB ist zu klein für ' + req + ' KB.'; wr[b - req] = 'Das ist die Verschwendung, nicht die Blockgröße.';
    if (b === req) { delete wr[req]; delete wr[0]; }
    return { q: 'Binärer Buddy-Allokator mit 64 KB. Anfrage über **' + req + ' KB**. Wie groß ist der vergebene Block **in KB**?', num: b, unit: 'KB', hint: 'Zweierpotenz in KB', e: '**Rechenweg:** Kleinste Zweierpotenz ≥ ' + req + ' KB: **' + b + ' KB**.\nInterne Fragmentierung: ' + b + ' − ' + req + ' = ' + (b - req) + ' KB.', s: 2, wr: wr };
  } });
  add('t4', { n: 3, f: function (r) {
    var sz = u.pick(r, [4, 8, 16]), idx = u.ri(r, 0, 64 / sz - 1), a = idx * sz, v = a ^ sz, wr = {};
    wr[a + sz === v ? -1 : a + sz] = 'Der Buddy kann auch links liegen – es kippt genau das Bit für ' + sz + ' KB.'; wr[a - sz === v ? -1 : a - sz] = 'Der Buddy kann auch rechts liegen – es kippt genau das Bit für ' + sz + ' KB.';
    return { q: 'Buddy-Allokator (Bereich ab 0). Ein **' + sz + '-KB**-Block liegt bei Adresse **' + a + ' KB**. Bei welcher Adresse (in KB) liegt sein Buddy?', num: v, unit: 'KB', hint: 'Ganze Zahl in KB', e: '**Rechenweg:** Buddies unterscheiden sich in genau einem Bit – dem Bit für die Blockgröße ' + sz + '.\n' + a + ' = ' + u.bin(a, 6) + ' → Bit für ' + sz + ' kippen → ' + u.bin(v, 6) + ' = **' + v + ' KB**.', s: 3, wr: wr };
  } });

  C.topics.forEach(function (t) { if (t.st) t.st.n = 4; (t.gen || []).forEach(function (g) { g.n = Math.min(4, Math.max(2, g.n > 4 ? Math.round(g.n / 3) : g.n)); }); });

  var X = OSTEP.ex = OSTEP.ex || {}, D = OSTEP.dw = OSTEP.dw || {}, L = OSTEP.lang = OSTEP.lang || {};
  function pack(key, rows) { X[key] = rows.map(function (r) { return [null, r[0]]; }); D[key] = rows.map(function (r) { return r[1]; }); L[key] = L[key] || {}; L[key].q = rows.map(function (r) { return r[2]; }); }
  pack('17-t1', [
    [['Verschwendung innerhalb eines Blocks ist interne Fragmentierung.', 'Mit Hardwaredefekten hat das nichts zu tun.', 'Die Zahl der Prozesse ist nicht der Punkt.'], 'Genug Speicher frei – aber in Stücken. | Keine einzelne Lücke ist groß genug. | Verschwendung außerhalb der Blöcke → extern.', 'Externe Fragmentierung heißt laut Buch: Der freie Speicher ist in **viele kleine Stücke unterschiedlicher Größe** zerfallen. Spätere Anfragen scheitern, weil es **keinen zusammenhängenden** Bereich gibt, der groß genug ist – obwohl insgesamt mehr frei ist als angefragt.'],
    [['Insgesamt sind 20 frei, aber kein Stück hat 15.', 'Splitting teilt nur – es macht kein Stück größer.', 'Paging spielt bei malloc keine Rolle.'], 'malloc braucht einen zusammenhängenden Bereich. | Größtes Stück: 10 Bytes. | 15 > 10 → scheitert.', 'Genau dieses Beispiel bringt das Buch: **20 Bytes** frei, aber zerteilt in **zwei Stücke à 10**. Eine Anfrage über **15 Bytes scheitert**, obwohl genug Speicher frei ist – das ist externe Fragmentierung.'],
    [['Variable Größen sind gerade das schwierige Problem.', 'Wachstum ändert nichts an der Grundschwierigkeit.', 'Zeiger gibt es in C immer.'], 'Was macht Freispeicherverwaltung schwer? | Unterschiedlich große Anfragen hinterlassen unterschiedlich große Lücken. | Gleich große Stücke → jede Lücke passt.', 'Laut Buch ist Freispeicherverwaltung **einfach**, wenn der Speicher in **gleich große Einheiten** zerlegt ist (wie beim Paging): Man hält eine Liste dieser Einheiten und gibt bei Bedarf die erste zurück. Schwierig wird es bei **variabel großen** Anfragen.'],
    [['Den Zeiger bekommt free() sehr wohl.', 'Die Startadresse ist der Zeiger.', 'Doch – die Größe fehlt.'], 'Die Schnittstelle lautet free(void *ptr). | Nur ein Zeiger, keine Größe. | → die Bibliothek muss die Größe selbst herausfinden.', 'Die Schnittstelle `void free(void *ptr)` bekommt **nur den Zeiger**. Daraus folgt laut Buch: Die Bibliothek muss selbst herausfinden können, **wie groß** der Bereich ist – dafür gibt es den Header.'],
    [['Die Heapgröße ist nicht das Problem.', 'Die CPU verbietet nichts.', 'free() hat damit nichts zu tun.'], 'Das Programm hält Zeiger auf seine Bereiche. | Verschiebt man einen Bereich, zeigen die Zeiger ins Leere. | → in C keine Kompaktierung.', 'Sobald ein Programm einen Zeiger auf einen Bereich hat, „gehört“ ihm dieser Bereich laut Buch, bis es ihn mit free() zurückgibt. Die Bibliothek darf ihn **nicht verschieben**, deshalb ist **keine Kompaktierung** möglich. In C lassen sich außerdem nicht alle Zeiger finden (sie können in Variablen oder Registern stehen).'],
    [['Ein Eintrag [0, 30] gälte für einen ganz freien Heap.', '[10, 10] ist der belegte Bereich.', 'Das zweite Stück beginnt bei 20 und ist 10 lang.'], 'Frei sind 0–9 und 20–29. | Jedes freie Stück = ein Eintrag (Adresse, Länge). | → [0, 10] → [20, 10].', 'Die Free List beschreibt jedes freie Stück mit **Adresse und Länge**. Für den 30-Byte-Heap aus dem Buch (frei 0–9, belegt 10–19, frei 20–29) hat sie zwei Einträge: **addr 0, len 10** und **addr 20, len 10**.'],
    [['Ohne Änderung wäre das eine Byte nicht vergeben.', 'Bedient wurde das zweite Stück.', 'Das erste Stück bleibt unberührt.'], 'Splitting aus [20, 10]: Byte 20 geht an den Aufrufer. | Der Rest beginnt bei 21. | Länge 10 − 1 = 9.', 'Laut Buch liefert malloc(1) die Adresse **20**, und der Eintrag wird zu **[21, 9]**. Die Liste bleibt sonst unverändert – das erste Stück [0, 10] bleibt, wie es ist.'],
    [['Das Verschmelzen heißt Coalescing.', 'Verdoppeln gibt es nicht.', 'Prozesse werden nicht geteilt.'], 'Anfrage kleiner als ein freies Stück. | Stück teilen: vorne an den Aufrufer, Rest bleibt frei. | → Splitting.', '**Splitting** heißt laut Buch: Der Allokator findet ein passendes freies Stück und **teilt es in zwei**. Das erste geht an den Aufrufer, das zweite bleibt in der Liste. Man nutzt es, wenn Anfragen kleiner sind als die freien Stücke.'],
    [['Teilen ist Splitting.', 'Komprimieren wäre Kompaktierung.', 'Zeiger werden nicht umgeschrieben.'], 'Freigabe: Liegt das Stück neben freien Nachbarn? | Wenn ja → zusammenführen. | → ein großes Stück statt vieler kleiner.', '**Coalescing** heißt laut Buch: Beim Zurückgeben eines Stücks schaut der Allokator auf die Adressen der Nachbarn. Liegt das neu freie Stück direkt neben freien Stücken, werden sie zu **einem größeren** verschmolzen.'],
    [['Ohne Coalescing ist kein Stück 20 Bytes groß.', 'Es gibt keinen Zufall – es scheitert immer.', 'Splitting macht nichts größer.'], 'Ohne Coalescing: drei Einträge à 10. | Alles ist frei, aber kein Stück hat 20 Bytes. | → malloc(20) scheitert.', 'Genau das zeigt das Buch: Wird der mittlere Block einfach in die Liste gehängt, entsteht **[10,10] → [0,10] → [20,10]**. Der ganze Heap ist frei, aber in drei Stücke à 10 zerteilt – eine Anfrage über **20 Bytes scheitert**.'],
    [['Ohne Coalescing würde er bloß vorne angehängt.', 'Der Block liegt direkt zwischen beiden freien Stücken.', 'Ohne Freigabe ändert sich nichts.'], 'Freigegeben wird 10–19. | Links grenzt 0–9, rechts 20–29 an – beide frei. | Alle drei verschmelzen → [0, 30].', 'Mit **Coalescing** prüft der Allokator die Nachbarn: Das freigegebene Stück [10, 10] grenzt links an [0, 10] und rechts an [20, 10]. Alle drei werden zu **[0, 30]** verschmolzen – laut Buch genau der Zustand vor allen Allokationen.'],
    [['Beim Booten gibt es noch nichts zu verschmelzen.', 'Eine feste Anzahl nennt das Buch nicht.', 'Ohne Coalescing würde der Heap zerfallen.'], 'Wann können neue Nachbarn frei werden? | Genau dann, wenn ein Stück zurückgegeben wird. | → beim Freigeben.', 'Laut Buch führen Allokatoren Coalescing durch, **wenn ein Stück freigegeben wird**: Sie schauen auf die Adressen des zurückgegebenen und der benachbarten freien Stücke und verschmelzen sie gegebenenfalls.'],
    [['Die Page Table gehört zum Paging.', 'Die Run Queue gehört zum Scheduler.', 'Inodes gehören zum Dateisystem.'], 'Eine Struktur, die alle freien Stücke kennt. | Historisch meist eine Liste. | → Free List.', 'Die Datenstruktur, die alle freien Stücke des Heaps verwaltet, heißt laut Buch **Free List**. Es muss keine Liste im engeren Sinn sein – nur irgendeine Struktur, die den freien Platz verfolgt.'],
    [['Die Adresse 4 wäre schon hinter dem vergebenen Bereich.', 'Der Eintrag muss nach dem Vergeben kleiner und verschoben sein.', 'Bedient wird das erste Stück, nicht das bei 20.'], 'Splitting aus [0, 10]: vorne 4 Bytes an den Aufrufer. | Aufrufer bekommt Adresse 0. | Rest: ab 4, Länge 6 → [4, 6].', 'Beim **Splitting** gibt der Allokator den **vorderen Teil** des Stücks an den Aufrufer: Er bekommt Adresse **0**. Der Rest bleibt in der Liste, beginnt nun bei **4** und ist **6** Bytes lang. Genau so verläuft das Buchbeispiel mit malloc(1) aus [20, 10] → Adresse 20, Rest [21, 9].'],
    [['Die Zahl der CPUs ist nicht der Grund.', 'Gleich große Seiten verhindern das gerade.', 'Systemaufrufe verursachen keine Lücken.'], 'Unterschiedlich große Anfragen und Freigaben. | → unterschiedlich große Lücken. | → Zerstückelung.', 'Externe Fragmentierung entsteht laut Buch, wenn **variabel große** Anfragen bedient und wieder freigegeben werden. Der freie Speicher zerfällt dabei in Stücke unterschiedlicher Größe.'],
    [['Scheduling verwaltet keine Speicherstücke.', 'Das Buch nennt Segmentierung im OS.', 'Doch – auch das OS verwaltet Speicher.'], 'Wer verwaltet noch variabel große Stücke? | Das OS bei Segmentierung (Segmente unterschiedlicher Größe). | Dort ist sogar Kompaktierung möglich.', 'Das Problem tritt laut Buch nicht nur in malloc-Bibliotheken auf, sondern auch im **Betriebssystem**, z. B. bei der **Segmentierung** mit variabel großen Segmenten. Dort kann das OS – anders als malloc – sogar **kompaktieren**.'],
    [['Unendlich groß ist kein Heap.', 'Wachsen wird erst später besprochen.', 'Ein Heap der Größe 0 wäre nutzlos.'], 'Das Buch vereinfacht: ein zusammenhängender Bereich. | Er soll sein ganzes Leben gleich groß bleiben. | → feste Größe.', 'Das Kapitel nimmt laut Buch der Einfachheit halber an, dass der Allokator einen **zusammenhängenden Bereich fester Größe** verwaltet. In Wirklichkeit kann eine Bibliothek den Heap per **sbrk** vergrößern.'],
    [['Gelöscht wird nichts – der Eintrag schrumpft nur.', 'Doch – der Eintrag ändert sich.', 'Die Liste wird nicht geleert.'], 'Vorne geht ein Teil weg. | → Startadresse rückt nach hinten, Länge sinkt. | Sonst bleibt die Liste gleich.', 'Laut Buch bleibt die Liste beim Splitting **im Wesentlichen intakt**: Nur der betroffene Eintrag ändert sich – er beginnt später (z. B. 21 statt 20) und ist kürzer (9 statt 10).'],
    [['Verstreute Stücke sind externe Fragmentierung.', 'Fehlendes Coalescing führt zu externer Fragmentierung.', 'Splitting erzeugt kleinere Lücken, aber keine interne Verschwendung.'], 'Interne Verschwendung = innerhalb eines vergebenen Blocks. | Entsteht, wenn mehr vergeben wird als verlangt. | Der Rest im Block bleibt ungenutzt.', 'Laut Buch entsteht **interne Fragmentierung**, wenn ein Allokator **größere Stücke vergibt als angefordert**: Der nicht verlangte Platz im Stück bleibt ungenutzt, die Verschwendung liegt **innerhalb** der Einheit.'],
    [['Teuer wäre es, aber vor allem ist es unmöglich.', 'Das OS ist hier nicht beteiligt.', 'Der Heap ist beschreibbar.'], 'Wer hält Zeiger auf vergebene Bereiche? → das Programm. | Verschieben → Zeiger falsch. | → nicht erlaubt.', 'Vergebene Bereiche dürfen laut Buch **nicht verschoben** werden, weil das Programm Zeiger darauf hält. In C kann man diese Zeiger nicht zuverlässig finden – sie können überall in Variablen oder Registern stehen. Kompaktierung scheidet daher aus.']
  ]);
  pack('17-t2', [
    [['Dateien nutzt malloc dafür nicht.', 'Das PCB gehört dem OS, nicht der Bibliothek.', 'Der TLB speichert Übersetzungen.'], 'free() bekommt nur einen Zeiger. | Die Größe muss also beim Bereich stehen. | → in einem Header direkt davor.', 'Die meisten Allokatoren speichern laut Buch zusätzliche Informationen in einem **Header**, der **direkt vor** dem vergebenen Bereich im Speicher liegt. Mindestens steht dort die **Größe**.'],
    [['Die PID kennt malloc nicht.', 'Ein Dateiname hat dort nichts zu suchen.', 'Die Uhrzeit wird nicht gespeichert.'], 'Header: Größe plus Zusatzinfos. | Eine feste Zahl zur Kontrolle. | → Magic Number.', 'Neben der Größe kann der Header laut Buch weitere Zeiger zur schnelleren Freigabe und eine **Magic Number** zur Integritätsprüfung enthalten. Im Buchbeispiel ist magic = 1234567.'],
    [['Plus würde hinter den Bereich zeigen.', 'Mal 2 ergibt keine sinnvolle Adresse.', 'Eine Hash-Tabelle braucht man nicht.'], 'Header liegt direkt vor dem Bereich. | Also: Zeiger um eine Headergröße zurück. | (header_t *) ptr − 1.', 'free() findet den Header laut Buch mit einfacher Zeigerarithmetik: `header_t *hptr = (header_t *) ptr - 1;` – also **ptr − sizeof(header_t)**.'],
    [['Der Header kostet zusätzlich Platz.', 'Weniger als angefragt geht nicht.', '2N wäre absurde Verschwendung.'], 'Gebraucht werden N Bytes für den Nutzer. | Plus der Header davor. | → N + Headergröße.', 'Laut Buch sucht die Bibliothek bei einer Anfrage über N Bytes **nicht** nach einem Stück der Größe N, sondern nach **N plus Headergröße**. Im Beispiel belegt malloc(100) daher **108 Bytes**.'],
    [['Die Geschwindigkeit ist nicht das Problem.', 'Listen sind erlaubt.', 'Das OS verlangt nichts.'], 'Die Free List ist Teil des Allokators. | malloc() für die Liste aufzurufen wäre ein Kreis. | → Liste im freien Speicher selbst.', 'Normalerweise würde man für einen neuen Listenknoten malloc() aufrufen. **Innerhalb** der Speicherbibliothek geht das laut Buch nicht! Die Liste wird deshalb **im freien Speicher selbst** aufgebaut.'],
    [['Magic gehört in den Header belegter Blöcke.', 'prev und data hat der Knoten im Buch nicht.', 'Eine PID gibt es dort nicht.'], 'Ein Listenknoten braucht: Wie groß ist dieses freie Stück? | Und: Wo ist das nächste? | → size und next.', 'Ein Knoten der eingebetteten Liste ist laut Buch `typedef struct __node_t { int size; struct __node_t *next; } node_t;` – also **size** und **next**.'],
    [['4096 ist der ganze Heap inkl. Knoten.', '4080 zieht zu viel ab.', 'Mehr als der Heap geht nicht.'], 'Heap: 4096 Bytes. | Am Anfang steht der Knoten (8 Bytes). | size = 4096 − 8 = 4088.', 'Laut Buch wird der Kopf mit `head->size = 4096 - sizeof(node_t);` angelegt. Bei 8 Bytes pro Knoten ergibt das **4088**.'],
    [['3988 vergisst den Header.', '3888 zieht 200 ab.', '4088 wäre ohne Allokation.'], 'Belegt: 100 + 8 Header = 108. | 4088 − 108 = 3980.', 'Laut Buch belegt die Anfrage über 100 Bytes **108 Bytes** (mit 8-Byte-Header). Das freie Stück schrumpft auf **3980** Bytes (4088 − 108).'],
    [['300 vergisst die Header.', '308 zählt nur einen Header.', '332 zählt einen Header zu viel.'], 'Pro Anfrage: 100 + 8 = 108. | 3 · 108 = 324.', 'Laut Buch sind nach drei Anfragen à 100 Bytes die ersten **324 Bytes** des Heaps belegt – drei Header plus drei 100-Byte-Bereiche.'],
    [['7784 vergisst die beiden Header.', '7776 vergisst den Listenknoten am Anfang.', '7976 zählt nur eine Anfrage.'], 'Anfangs: 8192 − 8 = 8184. | Pro Anfrage: 200 + 8 = 208. | 8184 − 2 · 208 = 7768.', 'Wie im Buchbeispiel (4096 → 4088 → 3980 → … → 3764): Erst kostet der **Listenknoten** 8 Bytes, dann jede Anfrage **Größe plus 8 Bytes Header**. 8184 − 416 = **7768**.'],
    [['Das Buch fügt am Kopf ein, nicht am Ende.', 'Freie Blöcke müssen in die Liste.', 'Eine Sortierung nach Größe macht das Beispiel nicht.'], 'Einfachste Variante: vorne einhängen. | Im Buch: „insert at the head“.', 'Im Beispiel nimmt das Buch an, dass der freigegebene Block **am Kopf der Free List** eingefügt wird. Danach beginnt die Liste mit dem kleinen 100-Byte-Stück.'],
    [['fork() erzeugt Prozesse.', 'read() liest Dateien.', 'Der Stack ist kein Heap.'], 'Das Beispiel braucht einen Speicherbereich für den Heap. | Das Buch nutzt dafür einen Systemaufruf. | → mmap().', 'Im Buchbeispiel wird der Heap in einem Bereich angelegt, den der Systemaufruf **mmap()** liefert: `node_t *head = mmap(NULL, 4096, …);` – nicht der einzige Weg, aber für das Beispiel praktisch.'],
    [['fork() erzeugt einen neuen Prozess.', 'exec() lädt ein Programm.', 'wait() wartet auf ein Kind.'], 'Heap voll → mehr Speicher vom OS. | Unter Unix über einen Systemaufruf. | → sbrk().', 'Die meisten klassischen Allokatoren starten laut Buch mit einem kleinen Heap und fordern bei Bedarf **mehr Speicher vom OS** an – unter Unix meist per **sbrk**.'],
    [['Das Programm muss nicht sterben.', 'Ein Neustart ist absurd.', 'Fremder Speicher ist tabu.'], 'Was tun, wenn nichts mehr frei ist? | Einfachste Lösung: scheitern. | → NULL zurückgeben.', 'Die einfachste Reaktion ist laut Buch, **einfach zu scheitern** und **NULL** zurückzugeben – „ein ehrenhafter Ansatz“. Viele Allokatoren holen sich stattdessen per sbrk mehr Speicher.'],
    [['Ohne Coalescing entsteht gerade kein großes Stück.', 'Freigeben stürzt nicht ab.', 'Die Liste bleibt bestehen.'], 'Drei Blöcke frei, einfach an den Kopf gehängt. | Niemand verschmilzt Nachbarn. | → viele Stücke statt einem.', 'Laut Buch entsteht ohne Coalescing ein „big mess“ (Figure 17.7): **Der ganze Speicher ist frei**, aber in Stücke zerhackt – er wirkt fragmentiert, obwohl er es nicht sein müsste. Lösung: Liste durchgehen und Nachbarn verschmelzen.'],
    [['Prozesse werden nicht verschoben.', 'Der Stack bleibt unberührt.', 'Dateien haben damit nichts zu tun.'], 'sbrk fordert Speicher an. | Das OS braucht physische Seiten dafür. | → finden und in den Adressraum abbilden.', 'Um sbrk zu bedienen, **findet das OS freie physische Seiten**, bildet sie in den **Adressraum** des Prozesses ab und gibt das **neue Heap-Ende** zurück.'],
    [['Verschlüsselung macht malloc nicht.', 'Eine PID steht dort nicht.', 'Die Größe steht im size-Feld.'], 'free() bekommt einen Zeiger. | Ist das wirklich ein Block von malloc? | Magic Number prüfen.', 'Die **Magic Number** dient laut Buch als **Plausibilitätsprüfung**: `assert(hptr->magic == 1234567)`. Passt sie nicht, hat free() wahrscheinlich einen falschen Zeiger bekommen.'],
    [['4 Bytes reichen nur für size.', '16 Bytes wären zwei Felder mehr.', '1 Byte ist zu wenig.'], 'size: int (4 Bytes). | magic: int (4 Bytes). | → 8 Bytes.', 'Der Header im Buch hat zwei int-Felder: **size** und **magic**. Bei 4 Bytes pro int sind das **8 Bytes** – daher kostet malloc(100) im Beispiel 108 Bytes.'],
    [['Der Header ist intern.', 'Die Größe kennt der Aufrufer schon.', 'Der Index ist ein internes Detail.'], 'Header gehört der Bibliothek. | Das Programm soll nur seinen Bereich sehen. | → Zeiger direkt hinter den Header.', 'malloc gibt einen Zeiger auf den **Nutzbereich** zurück, der **direkt hinter dem Header** beginnt (ptr in Figure 17.1). Den Header davor nutzt die Bibliothek später bei free().'],
    [['Die Größe ist kein Parameter von free().', 'Bytes zählen ist unmöglich.', 'Doch – über den Header.'], 'Header lesen → size. | Dazu kommt der Header selbst. | Gesamt = size + sizeof(header_t).', 'Laut Buch berechnet free() die Gesamtgröße des frei werdenden Bereichs als **Größe des Headers plus Größe des Nutzbereichs**. Ein kleines, aber entscheidendes Detail.']
  ]);
  pack('17-t3', [
    [['Den größten wählt Worst Fit.', 'Den ersten wählt First Fit.', 'Zufall ist keine der Strategien.'], 'Alle passenden Stücke betrachten. | Das kleinste davon nehmen. | → möglichst wenig Rest.', '**Best Fit** durchsucht laut Buch die Liste, sammelt alle Stücke, die groß genug sind, und gibt das **kleinste** davon zurück („smallest fit“). So soll möglichst wenig Platz verschwendet werden.'],
    [['30 ist das größte passende Stück.', '10 ist zu klein für 15.', '20 passt.'], 'Passend: 30 und 20. | Kleinstes davon: 20.', 'Genau das Buchbeispiel: Best Fit durchsucht die **ganze** Liste und findet **20** als kleinstes passendes Stück. Danach lautet die Liste 10 → 30 → 5.'],
    [['20 ist nicht das größte.', '10 ist zu klein.', '30 passt.'], 'Worst Fit = das größte Stück. | Größtes: 30.', '**Worst Fit** wählt laut Buch das **größte** Stück – hier 30 – und lässt den großen Rest (15) in der Liste: 10 → 15 → 20.'],
    [['20 kommt erst nach 30.', '10 ist zu klein.', '30 passt als erstes.'], 'Von vorn durchgehen. | 10: zu klein. 30: passt → nehmen.', '**First Fit** nimmt das **erste** passende Stück. Im Buchbeispiel ist das 30 – das Ergebnis gleicht Worst Fit, aber die Suche endet früher.'],
    [['Am meisten verschwenden sie nicht beide.', 'Einen zweiten Zeiger braucht Next Fit.', 'Sortierte Listen setzen sie nicht voraus.'], 'Best: das kleinste passende. | Worst: das größte. | Beides erfährt man nur nach Durchsicht aller Stücke.', 'Laut Buch müssen **Best Fit und Worst Fit die ganze Liste durchsuchen**, um das kleinste bzw. größte passende Stück zu finden. Das kostet Zeit.'],
    [['Garantien gibt keine Strategie.', 'Header braucht man trotzdem.', 'Splitting braucht First Fit auch.'], 'First Fit hört beim ersten Treffer auf. | Keine vollständige Suche. | → schnell.', 'Der Vorteil von **First Fit** ist laut Buch die **Geschwindigkeit**: Es ist keine vollständige Suche nötig.'],
    [['Ganz durchsuchen muss es gerade nicht.', 'Den größten wählt Worst Fit.', 'Teilen kann es natürlich.'], 'First Fit beginnt immer vorne. | Dort wird immer wieder gesplittet. | → viele kleine Reste am Listenanfang.', 'Laut Buch „verschmutzt“ First Fit manchmal den **Anfang der Free List** mit kleinen Objekten, weil jede Suche dort beginnt. Daher wird die Ordnung der Liste wichtig.'],
    [['Nach Größe hilft nicht beim Verschmelzen.', 'Zufällige Reihenfolge erschwert es.', 'Ohne Liste geht es nicht.'], 'Coalescing braucht Nachbarn. | Nachbarn haben benachbarte Adressen. | → Liste nach Adressen sortieren.', 'Das Buch nennt **adressbasierte Sortierung**: Hält man die Liste **nach Adressen** geordnet, wird **Coalescing einfacher**, und die Fragmentierung sinkt tendenziell.'],
    [['Den größten wählt Worst Fit.', 'Ganz durchsuchen müssen Best und Worst Fit.', 'Teilen tut Next Fit auch.'], 'First Fit beginnt jedes Mal vorne. | Next Fit merkt sich, wo es aufgehört hat. | → nächster Start dort.', '**Next Fit** hält laut Buch einen **zusätzlichen Zeiger** auf die Stelle, an der zuletzt gesucht wurde, und beginnt die nächste Suche dort statt am Listenanfang.'],
    [['Den kleinsten findet nur Best Fit.', 'Eine Free List braucht es weiterhin.', 'Fragmentierung vermeidet keine Strategie ganz.'], 'Suchen verteilen sich über die ganze Liste. | → der Anfang wird nicht zerhackt. | Leistung ähnlich wie First Fit.', 'Die Idee von **Next Fit**: Die Suchen **gleichmäßiger über die Liste verteilen** und so das Zersplittern des Listenanfangs vermeiden. Die Leistung ist laut Buch ähnlich wie bei First Fit.'],
    [['First Fit ist schnell und in der Praxis brauchbar.', 'Next Fit ist ähnlich gut wie First Fit.', 'Doch – das Buch nennt eine.'], 'Studien laut Buch: | Eine Strategie führt zu viel Fragmentierung und ist trotzdem teuer. | → Worst Fit.', 'Laut Buch zeigen die meisten Studien, dass **Worst Fit schlecht abschneidet**: Es führt zu **übermäßiger Fragmentierung** und hat trotzdem hohe Kosten durch die vollständige Suche.'],
    [['Kleine Reste erzeugt eher Best Fit.', 'Schnell sucht Worst Fit gerade nicht.', 'Header braucht es trotzdem.'], 'Best Fit lässt oft winzige Reste. | Worst Fit will das Gegenteil. | → große, nützliche Reste lassen.', 'Die Idee von **Worst Fit** ist laut Buch, **große Stücke frei zu lassen** statt vieler kleiner Splitter, wie sie bei Best Fit entstehen können.'],
    [['Riesige Reste entstehen bei Worst Fit.', 'Reste entstehen fast immer.', 'Doppelte Einträge entstehen nicht.'], 'Best Fit wählt das knappste Stück. | Der Rest ist dann oft winzig. | Beispiel: 20 − 15 = 5.', 'Laut Buch passiert bei Best Fit **oft**, was im Beispiel zu sehen ist: Ein **kleiner Rest** (dort 5 Bytes) bleibt übrig – solche Splitter sind später kaum nutzbar.'],
    [['Best Fit kann bei passenden Eingaben schlecht sein.', 'Worst Fit schneidet meist schlecht ab.', 'Auch Next Fit ist nicht immer optimal.'], 'Die Anfragen bestimmt das Programm. | Jede Strategie kann bei ungünstigen Eingaben schlecht sein. | → hängt vom Workload ab.', 'Das Buch beschreibt **keinen „besten“ Ansatz**: Weil die Folge von Anfragen beliebig sein kann, kann **jede Strategie** bei den falschen Eingaben schlecht abschneiden. Je besser man den Workload kennt, desto besser kann man den Allokator anpassen.'],
    [['Das wäre Worst Fit (30 → 15).', 'Ohne Allokation bliebe die Liste so.', '10 ist nicht verschwunden.'], 'Best Fit wählt 20. | 20 − 15 = 5. | → 10 → 30 → 5.', 'So steht es im Buch: Nach Best Fit lautet die Liste **10 → 30 → 5**. Der kleine Rest von 5 Bytes ist typisch für Best Fit.'],
    [['Das wäre Best Fit (20 → 5).', 'Ohne Allokation bliebe die Liste so.', 'Das 10er-Stück verschwindet nicht.'], 'Worst Fit wählt 30. | 30 − 15 = 15. | → 10 → 15 → 20.', 'Laut Buch lautet die Liste nach Worst Fit **10 → 15 → 20**: Das größte Stück wurde geteilt, ein großer Rest bleibt.'],
    [['12 ist größer als 8.', '4 ist zu klein für 5.', '8 passt.'], 'Passend (≥ 5): 8 und 12. | Kleinstes davon: 8.', 'Best Fit sammelt alle passenden Stücke (8 und 12) und nimmt das **kleinste: 8**. Rest: 3 Bytes.'],
    [['12 kommt erst nach 8.', '4 ist zu klein.', '8 passt als erstes.'], 'Von vorn: 8 passt sofort. | → 8.', 'First Fit nimmt das **erste** passende Stück: **8** steht ganz vorne und passt – die Suche endet sofort.'],
    [['8 ist nicht das größte.', '4 ist zu klein.', '12 passt.'], 'Größtes Stück: 12. | → 12.', 'Worst Fit nimmt das **größte** Stück: **12**. Rest: 7 Bytes.'],
    [['Best und Worst Fit müssen alles ansehen.', 'Best Fit kann nicht vorzeitig enden.', 'Doch – bei zwei Strategien.'], 'Wer nimmt den ersten Treffer? → First Fit. | Wer sucht ab der letzten Stelle weiter und nimmt den ersten Treffer? → Next Fit.', 'Bei **First Fit** und **Next Fit** endet die Suche beim **ersten passenden** Stück – keine vollständige Suche nötig. Best und Worst Fit müssen dagegen laut Buch die ganze Liste durchsehen.']
  ]);
  pack('17-t4', [
    [['Eine Liste für alle ist der allgemeine Allokator.', 'Halbieren ist das Buddy-Prinzip.', 'Nur Zweierpotenzen vergibt der Buddy-Allokator.'], 'Eine Anwendung fragt oft dieselbe Größe an. | → eigene Liste nur für diese Größe. | Alles andere → allgemeiner Allokator.', 'Die Idee von **Segregated Lists** laut Buch: Hat eine Anwendung eine (oder wenige) **häufige Anfragegröße**, führt man **eine eigene Liste nur für Objekte dieser Größe**. Alle anderen Anfragen gehen an einen allgemeineren Allokator.'],
    [['Header braucht man trotzdem.', 'Unbegrenzten Speicher gibt es nicht.', 'Kompaktierung gibt es nicht.'], 'Eine Liste, eine Größe. | → kaum Fragmentierung. | → keine aufwendige Suche.', 'Die Vorteile sind laut Buch offensichtlich: Mit einem Speicherbereich nur für eine Größe ist **Fragmentierung kaum ein Problem**, und Anfragen der richtigen Größe werden **sehr schnell** bedient – ohne komplizierte Suche.'],
    [['Header lesen ist kein Problem.', 'Zeiger werden nicht verschoben.', 'sbrk ist nicht die offene Frage.'], 'Mehrere Listen → wie viel Speicher bekommt jede? | Zu wenig → Engpass, zu viel → Verschwendung.', 'Wie jede gute Idee bringt auch diese laut Buch neue Komplikationen: **Wie viel Speicher** soll man dem Pool für eine bestimmte Größe geben – und wie viel dem allgemeinen Pool?'],
    [['Linux und Torvalds nennt das Buch hier nicht.', 'Ritchie wird hier nicht genannt.', 'Knuth hat nichts damit zu tun.'], 'Das Buch nennt einen „uber-engineer“. | Der Allokator wurde für einen Kernel entwickelt. | → Jeff Bonwick, Solaris.', 'Der **Slab Allocator** stammt laut Buch von **Jeff Bonwick** und wurde für den **Solaris-Kernel** entwickelt. Bonwick leitete später auch das Dateisystem ZFS.'],
    [['Eine einzige Liste wäre kein Slab-Allokator.', 'Page Tables legt der Slab Allocator nicht an.', 'Swap Space hat damit nichts zu tun.'], 'Beim Booten weiß der Kernel, welche Objekte oft gebraucht werden. | Locks, Inodes … | → je ein Object Cache.', 'Beim Booten legt der Kernel laut Buch **Object Caches** für häufig benötigte Kernel-Objekte an, etwa **Locks** und **Inodes**. Jeder Cache ist eine Segregated Free List für eine Größe.'],
    [['Ein Absturz wäre fatal.', 'Andere Caches werden nicht sofort verkleinert.', 'NULL wäre unnötig – es gibt Nachschub.'], 'Cache wird knapp. | → mehr Speicher vom allgemeinen Allokator. | In Stücken namens Slabs.', 'Geht einem Cache der Platz aus, fordert er laut Buch **Slabs** vom **allgemeinen Allokator** an (ein Vielfaches der Seiten- und Objektgröße). Umgekehrt kann der allgemeine Allokator Slabs zurückholen, wenn alle Objekte darin frei sind – etwa wenn das VM-System Speicher braucht.'],
    [['Verschlüsselt sind sie nicht.', 'Sie liegen im Speicher.', 'Mit Headern hat das nichts zu tun.'], 'Objekte zu initialisieren und zu zerstören kostet Zeit. | Freie Objekte bleiben im Grundzustand. | → beim nächsten Mal sofort nutzbar.', 'Der Slab Allocator geht laut Buch über andere Segregated Lists hinaus: Er hält **freie Objekte vorinitialisiert**. Bonwick zeigte, dass Initialisieren und Zerstören teuer sind – so entfallen diese Zyklen pro Objekt.'],
    [['Beliebige Größen vergibt er gerade nicht.', '4-KB-Seiten sind Paging.', 'Vielfache von 3 ergeben keine Halbierungen.'], 'Der Speicher wird immer wieder halbiert. | Halbieren von 2^N ergibt Zweierpotenzen. | → nur Zweierpotenzen.', 'Im binären Buddy-Allokator ist der freie Speicher laut Buch ein Bereich der Größe **2^N**, der rekursiv **halbiert** wird. Vergeben werden deshalb nur **Blöcke mit Zweierpotenz-Größe**.'],
    [['7 KB ist keine Zweierpotenz.', '16 KB wäre größer als nötig.', '4 KB ist zu klein.'], '64 → 32 → 16 → 8. | 8 KB ≥ 7 KB, 4 KB wäre zu klein. | → 8 KB.', 'Das Buchbeispiel (Figure 17.8): 64 KB werden halbiert, bis ein Block groß genug ist und eine weitere Teilung zu klein wäre – **8 KB** für die 7-KB-Anfrage.'],
    [['Aufrunden auf 32 KB lässt Platz übrig.', '4 KB wäre bei 16-KB-Blöcken.', '44 KB ist der Rest des ganzen Bereichs.'], '20 KB → nächste Zweierpotenz: 32 KB. | 32 − 20 = 12 KB ungenutzt. | Verschwendung im Block = intern.', 'Der Buddy-Allokator rundet auf die nächste Zweierpotenz auf: **32 KB** für 20 KB. Die **12 KB** Unterschied sind **interne Fragmentierung** – laut Buch der typische Nachteil, weil nur Zweierpotenzen vergeben werden.'],
    [['Doch – durch das Aufrunden.', 'Externe Fragmentierung ist nicht das Hauptproblem.', 'Die Platte ist nicht beteiligt.'], 'Nur Zweierpotenzen. | Anfragen werden aufgerundet. | → Rest im Block = intern.', 'Laut Buch kann der Buddy-Allokator unter **interner Fragmentierung** leiden, weil er **nur Blöcke mit Zweierpotenz-Größe** vergeben darf.'],
    [['Interne Fragmentierung hat er gerade.', 'Beliebige Größen gehen nicht.', 'Er braucht eine Datenstruktur.'], 'Coalescing ist entscheidend für jeden Allokator. | Der Buddy-Allokator ist genau darauf ausgelegt. | → einfaches Coalescing.', 'Die „Schönheit“ der Buddy-Allokation liegt laut Buch darin, was beim **Freigeben** passiert: Weil sich der Buddy eines Blocks leicht bestimmen lässt, ist **Coalescing einfach**.'],
    [['Dann wären sie keine Buddies.', 'Um 1 unterscheiden sie sich nicht.', 'Verschiedene Blöcke haben verschiedene Adressen.'], 'Zwei Buddies = zwei Hälften eines Blocks. | Ihre Adressen unterscheiden sich nur im Bit dieser Größe. | → genau ein Bit.', 'Laut Buch unterscheiden sich die Adressen eines Buddy-Paars nur in **einem einzigen Bit** – welches, hängt von der Ebene im Buddy-Baum ab. Deshalb findet man den Buddy sehr einfach.'],
    [['Ein freier Buddy wird nicht ignoriert.', 'Geteilt wird beim Vergeben, nicht beim Freigeben.', 'Zurückgegeben wird an die Free List.'], 'Buddy frei → verschmelzen zu 16 KB. | Dann den Buddy des 16-KB-Blocks prüfen. | Rekursiv weiter.', 'Laut Buch prüft der Allokator beim Freigeben des 8-KB-Blocks, ob sein Buddy frei ist. Wenn ja, verschmelzen beide zu **16 KB**. Dann wird der Buddy des 16-KB-Blocks geprüft – und so weiter, **rekursiv** den Baum hinauf.'],
    [['Es geht über mehrere Stufen.', 'Es endet sehr wohl.', 'Eine feste Zahl gibt es nicht.'], 'Rekursiv nach oben. | Stopp, wenn ein Buddy belegt ist. | Oder wenn alles wieder ein Block ist.', 'Das rekursive Verschmelzen setzt sich laut Buch fort, bis entweder **der ganze freie Bereich wiederhergestellt** ist oder ein **Buddy belegt** ist.'],
    [['Zwei Halbierungen ergeben 16 KB.', 'Vier ergeben 4 KB.', 'Acht wären viel zu viele.'], '64 → 32 (1) → 16 (2) → 8 (3).', 'Von 64 KB auf 8 KB sind **drei Halbierungen** nötig: 64 → 32 → 16 → 8. Genau so zeigt es Figure 17.8 im Buch.'],
    [['Das Buch nennt mehr als Listen.', 'Paging ist ein anderes Kapitel.', 'Journaling gehört zu Dateisystemen.'], 'Problem: Listen skalieren schlecht. | Lösung 1: bessere Datenstrukturen (Bäume). | Lösung 2: Allokatoren für Mehrkernsysteme.', 'Unter „Other Ideas“ nennt das Buch **komplexere Datenstrukturen** wie **balancierte Binärbäume, Splay Trees oder teilweise geordnete Bäume** sowie Allokatoren, die gut auf **Mehrprozessorsystemen** funktionieren. Für die Praxis verweist es auf den glibc-Allokator.'],
    [['Speicher brauchen sie schon.', 'Splitting verhindern sie nicht.', 'Zu schnell sind sie gerade nicht.'], 'Viele freie Bereiche → lange Liste. | Suchen in langen Listen ist langsam. | → schlechte Skalierung.', 'Ein großes Problem vieler Ansätze ist laut Buch die **mangelnde Skalierung**: **Listen zu durchsuchen kann sehr langsam sein**. Fortgeschrittene Allokatoren nutzen daher komplexere Datenstrukturen.'],
    [['Ohne allgemeinen Allokator gingen andere Größen nicht.', 'Nicht nur beim Booten.', 'Auch Benutzerprogramme nutzen ihn.'], 'Segregated List nur für häufige Größen. | Alles andere? | → allgemeiner Allokator.', 'Laut Buch werden **alle Anfragen ohne eigene Liste** an einen **allgemeineren Allokator** weitergereicht. Beim Slab Allocator holen sich die Caches von dort auch ihre Slabs.'],
    [['Pages gehören zum Paging.', 'Buddies gehören zum Buddy-Allokator.', 'Frames sind physische Seiten.'], 'Der Cache holt sich Speicherstücke vom allgemeinen Allokator. | Diese Stücke gaben dem Allokator den Namen. | → Slabs.', 'Ein Object Cache besteht aus **Slabs** – Speicherstücken, die er vom allgemeinen Allokator anfordert. Sind alle Objekte eines Slabs frei, kann der allgemeine Allokator ihn zurückholen.']
  ]);

  var ST = {
    't1': { T: ['**Splitting**: ein freies Stück teilen – vorne an den Aufrufer, Rest bleibt frei.', '**Coalescing**: benachbarte freie Stücke beim Freigeben verschmelzen.', 'free(void *ptr) bekommt **nur den Zeiger** – die Größe muss die Bibliothek selbst kennen.', 'Das Programm hält Zeiger – vergebene Bereiche dürfen **nicht verschoben** werden.', 'Genug frei, aber **kein zusammenhängendes Stück** – das ist externe Fragmentierung.', 'Aus [20, 10] wird nach malloc(1) **[21, 9]** – die Adresse 20 geht an den Aufrufer.'],
            F: ['Falsch: Teilen ist Splitting, **Coalescing verschmilzt**.', 'Falsch: free() bekommt **nur den Zeiger**.', 'Falsch: Wegen der Zeiger ist **keine Kompaktierung** möglich.', 'Falsch: Verschwendung **innerhalb** eines Blocks ist interne Fragmentierung.', 'Falsch: Ohne Coalescing kann ein freier Heap in **viele Stücke** zerfallen.', 'Falsch: Der Rest beginnt bei **21**.'] },
    't2': { T: ['Der Header liegt **direkt vor** dem Bereich, den malloc zurückgibt.', 'hptr = (header_t *) ptr − 1 – also **ptr − sizeof(header_t)**.', 'Die Free List wird **im freien Speicher selbst** aufgebaut.', 'Ein node_t hat **size** und **next**.', 'Unter Unix vergrößert **sbrk** den Heap.', 'Eine Anfrage über N Bytes braucht **N + Header**.'],
            F: ['Falsch: Er liegt **davor**.', 'Falsch: malloc() kann man im Allokator selbst nicht nutzen – die Liste ist **eingebettet**.', 'Falsch: Der **Header** kommt dazu.', 'Falsch: Man gibt **NULL** zurück oder holt per sbrk mehr Speicher.', 'Falsch: Ohne **Coalescing** bleiben sie getrennt.', 'Falsch: Die Größe steht in **size**; magic dient der Prüfung.'] },
    't3': { T: ['Best Fit nimmt das **kleinste passende** Stück.', 'Worst Fit nimmt das **größte** Stück.', 'First Fit nimmt das **erste passende** Stück.', 'Next Fit hat einen **zusätzlichen Zeiger** auf die letzte Suchposition.', 'Nach **Adressen** sortierte Listen machen Coalescing einfacher.', 'Best und Worst Fit müssen die **ganze Liste** durchsuchen.'],
            F: ['Falsch: Best Fit nimmt das **kleinste passende**.', 'Falsch: Worst Fit schneidet in Studien meist **schlecht** ab.', 'Falsch: First Fit **endet beim ersten Treffer**.', 'Falsch: Next Fit sucht **ab der letzten Stelle** weiter.', 'Falsch: Laut Buch gibt es **keinen „besten“** Ansatz.', 'Falsch: **Adress**-sortierte Listen erleichtern Coalescing.'] },
    't4': { T: ['Segregated Lists: **eigene Listen** für häufige Größen.', 'Der Slab Allocator stammt von **Jeff Bonwick** für den **Solaris**-Kernel.', 'Freie Slab-Objekte bleiben **vorinitialisiert**.', 'Der binäre Buddy-Allokator vergibt **nur Zweierpotenzen**.', 'Buddy-Adressen unterscheiden sich in **genau einem Bit**.', 'Aufrunden auf Zweierpotenzen erzeugt **interne** Fragmentierung.'],
            F: ['Falsch: Aufrunden erzeugt **interne** Fragmentierung.', 'Falsch: Sie bleiben **vorinitialisiert**.', 'Falsch: Nur in **einem Bit**.', 'Falsch: 7 KB → **8 KB**.', 'Falsch: Jede häufige Größe hat eine **eigene** Liste.', 'Falsch: Coalescing ist beim Buddy-Allokator **besonders einfach**.'] }
  };
  var GT = {
    't1': ['Splitting gibt die vorderen Bytes des Stücks an den Aufrufer: Die neue Startadresse ist alte Adresse + angefragte Größe, die Länge sinkt um denselben Wert.', 'Ohne Coalescing bleibt jedes Stück einzeln. malloc braucht ein **zusammenhängendes** Stück – entscheidend ist das größte einzelne Stück, nicht die Summe.', 'Splitting: vorne wird abgegeben, der Rest beginnt bei Adresse + angefragter Größe.'],
    't2': ['Erst kostet der Listenknoten am Anfang seine Größe, dann jede Anfrage ihre Größe **plus** Header. Freier Rest = Heap − Knoten − n · (Größe + Header).', 'Der Header liegt direkt vor dem Bereich: Headeradresse = ptr − Headergröße.', 'Der Header liegt direkt vor dem Bereich, den das Programm bekommen hat – also ptr minus Headergröße.', 'Rechne erst den Listenknoten ab, dann jede Anfrage mit ihrem Header.'],
    't3': ['Prüfe zuerst, welche Stücke groß genug sind. Best Fit nimmt das kleinste davon, Worst Fit das größte, First Fit das erste in Listenreihenfolge. Der Rest ist Stückgröße minus Anfrage.', 'Erst die passenden Stücke bestimmen, dann je nach Strategie wählen (kleinstes, größtes oder erstes) und die Anfrage abziehen.'],
    't4': ['Der Buddy-Allokator halbiert so lange, bis eine weitere Halbierung zu klein wäre – er vergibt also die kleinste Zweierpotenz ≥ Anfrage. Die Differenz ist interne Fragmentierung.', 'Buddies unterscheiden sich in genau einem Bit – dem Bit, das der Blockgröße entspricht. Adresse XOR Blockgröße ergibt den Buddy.', 'Kleinste Zweierpotenz, die mindestens so groß ist wie die Anfrage.', 'Kippe in der Adresse genau das Bit mit dem Wert der Blockgröße.']
  };
  Object.keys(ST).forEach(function (tid) { var k = '17-' + tid; L[k] = L[k] || {}; L[k].T = ST[tid].T; L[k].F = ST[tid].F; L[k].g = GT[tid]; });

  /* ---------- Begriffe ---------- */
  OSTEP.terms = OSTEP.terms || {};
  OSTEP.terms[17] = [
    { t: 'Externe Fragmentierung', d: 'Genug frei – aber zerstückelt', k: 't1', s: 0, e: 'Der freie Speicher ist in viele kleine Stücke zerfallen. Eine Anfrage scheitert, obwohl insgesamt genug frei ist. Buchbeispiel: 20 Bytes frei in zwei Stücken à 10 → malloc(15) scheitert.', v: { type: 'heap', size: 30, title: '30-Byte-Heap', frames: [{ note: '20 Bytes frei …', blocks: [['', 10], ['A', 10], ['', 10]] }, { note: '… aber malloc(15) scheitert: kein Stück ≥ 15', blocks: [['', 10], ['A', 10], ['', 10]] }] } },
    { t: 'Interne Fragmentierung', d: 'Verschwendung im Block', k: 't1', s: 1, e: 'Vergibt ein Allokator **mehr als angefordert**, bleibt der Rest im vergebenen Block ungenutzt. Typisch beim Buddy-Allokator, der auf Zweierpotenzen aufrundet.', v: { type: 'heap', size: 8, title: 'malloc(7 KB) im Buddy-System', frames: [{ note: 'Vergeben wird ein 8-KB-Block', blocks: [['A', 7, '7 KB'], ['A', 1, '1']] }, { note: '1 KB im Block bleibt ungenutzt', blocks: [['A', 7, '7 KB genutzt'], ['', 1, '1 KB']] }] } },
    { t: 'Free List', d: 'Verzeichnis der freien Stücke', k: 't1', s: 1, e: 'Datenstruktur, die alle freien Stücke des Heaps kennt – je Eintrag Adresse und Länge. Es muss keine Liste im engeren Sinn sein.', v: { type: 'heap', size: 30, title: 'Free List eines 30-Byte-Heaps', frames: [{ note: 'head → [0, 10] → [20, 10] → NULL', blocks: [['', 10], ['A', 10], ['', 10]] }] } },
    { t: 'Splitting', d: 'Ein freies Stück teilen', k: 't1', s: 2, e: 'Ist die Anfrage kleiner als ein freies Stück, wird es geteilt: vorne an den Aufrufer, Rest bleibt in der Liste. malloc(1) aus [20, 10] → Adresse 20, Liste [21, 9].', v: { type: 'heap', size: 30, title: 'Splitting: malloc(1)', frames: [{ note: 'Vorher: [0, 10] → [20, 10]', blocks: [['', 10], ['A', 10], ['', 10]] }, { note: 'Nachher: [0, 10] → [21, 9]', blocks: [['', 10], ['A', 10], ['B', 1, '1'], ['', 9]] }] } },
    { t: 'Coalescing', d: 'Freie Nachbarn verschmelzen', k: 't1', s: 3, e: 'Beim Freigeben prüft der Allokator die Nachbarn. Liegen freie Stücke direkt daneben, werden sie zu einem großen verschmolzen. Ohne Coalescing bleibt ein ganz freier Heap zerstückelt.', v: { type: 'heap', size: 30, title: 'free(10) mit und ohne Coalescing', frames: [{ note: 'Ohne: [10,10] → [0,10] → [20,10]', blocks: [['', 10], ['', 10], ['', 10]] }, { note: 'Mit Coalescing: [0, 30]', blocks: [['', 30]] }] } },
    { t: 'Header & Magic Number', d: 'Größe direkt vor dem Block', k: 't2', s: 0, e: 'malloc speichert vor jedem vergebenen Bereich einen **Header** mit der Größe und oft einer **Magic Number** (z. B. 1234567) zur Prüfung. free(ptr) findet ihn bei ptr − sizeof(header_t).', v: { type: 'code', title: 'Header (Buchbeispiel)', code: 'typedef struct {\n    int size;   // 20\n    int magic;  // 1234567\n} header_t;\n\nvoid free(void *ptr) {\n    header_t *hptr = (header_t *) ptr - 1;\n    assert(hptr->magic == 1234567);\n}' } },
    { t: 'Eingebettete Free List', d: 'Die Liste lebt im freien Speicher', k: 't2', s: 1, e: 'Im Allokator selbst kann man kein malloc() aufrufen – die Listenknoten (size, next) liegen deshalb **im freien Speicher**. Ein 4096-Byte-Heap startet mit size = 4088.', v: { type: 'heap', size: 4096, title: '4-KB-Heap (Buchbeispiel)', frames: [{ note: 'Start: ein Knoten, size = 4088', blocks: [['', 4096, '4088']] }, { note: 'malloc(100): 108 Bytes belegt', blocks: [['A', 900, '108'], ['', 3196, '3980']] }, { note: 'Drei Anfragen: 324 Bytes belegt', blocks: [['A', 600, '108'], ['B', 600, '108'], ['C', 600, '108'], ['', 2296, '3764']] }] } },
    { t: 'sbrk', d: 'Den Heap vergrößern', k: 't2', s: 3, e: 'Ist der Heap voll, kann der Allokator NULL zurückgeben – oder per Systemaufruf **sbrk** mehr Speicher holen. Das OS findet freie physische Seiten und bildet sie in den Adressraum ab.', v: { type: 'points', title: 'Heap voll – was nun?', items: [['🙅', 'einfachste Lösung: NULL zurückgeben'], ['📞', 'sbrk(): OS um mehr Speicher bitten'], ['🗺️', 'OS bildet freie Seiten in den Adressraum ab'], ['✅', 'neues Heap-Ende → Anfrage klappt']] } },
    { t: 'Best Fit', d: 'Das kleinste passende Stück', k: 't3', s: 0, e: 'Durchsucht die ganze Liste und nimmt das kleinste Stück, das groß genug ist. Wenig Verschwendung pro Anfrage, aber teure Suche und oft winzige Reste.', v: { type: 'fit', free: [10, 30, 20], req: 15, strat: 'best', note: 'Kleinstes passendes Stück: 20 → Rest 5' } },
    { t: 'Worst Fit', d: 'Das größte Stück', k: 't3', s: 1, e: 'Nimmt das größte Stück, um große Reste zu lassen. Braucht ebenfalls eine vollständige Suche – und schneidet laut Studien meist schlecht ab.', v: { type: 'fit', free: [10, 30, 20], req: 15, strat: 'worst', note: 'Größtes Stück: 30 → Rest 15' } },
    { t: 'First Fit', d: 'Das erste passende Stück', k: 't3', s: 2, e: 'Nimmt das erste Stück, das passt – schnell, aber der Listenanfang füllt sich mit kleinen Splittern. Eine **nach Adressen** sortierte Liste erleichtert Coalescing.', v: { type: 'fit', free: [10, 30, 20], req: 15, strat: 'first', note: 'Erstes passendes Stück: 30 – Suche endet sofort' } },
    { t: 'Next Fit', d: 'Weitersuchen, wo man aufhörte', k: 't3', s: 3, e: 'Wie First Fit, aber mit einem zusätzlichen Zeiger auf die letzte Suchposition. So verteilen sich die Suchen gleichmäßiger, und der Listenanfang zersplittert weniger.', v: { type: 'points', title: 'Next Fit', items: [['📍', 'merkt sich die letzte Suchposition'], ['➡️', 'nächste Suche beginnt dort'], ['🧩', 'Anfang der Liste splittert weniger'], ['⚡', 'Leistung ähnlich wie First Fit']] } },
    { t: 'Segregated Lists & Slab', d: 'Eigene Listen für häufige Größen', k: 't4', s: 1, e: 'Für häufige Objektgrößen gibt es eigene Listen. Der **Slab Allocator** (Jeff Bonwick, Solaris) legt beim Booten Object Caches z. B. für Locks und Inodes an, holt sich bei Bedarf **Slabs** und hält freie Objekte **vorinitialisiert**.', v: { type: 'table', cmp: true, cols: ['Cache: Locks', 'Cache: Inodes', 'allgemein'], rows: [[0, 'Lock'], [0, 'Lock'], [0, 'frei (init.)'], [1, 'Inode'], [1, 'frei (init.)'], [1, 'frei (init.)'], [2, 'alle anderen'], [2, 'Größen'], [2, '+ neue Slabs']] } },
    { t: 'Buddy-Allokator', d: 'Halbieren und verschmelzen', k: 't4', s: 2, e: 'Der Speicher (2^N) wird halbiert, bis der Block gerade groß genug ist (7 KB → 8 KB aus 64 KB). Beim Freigeben verschmilzt ein Block mit seinem freien **Buddy** – die Adressen unterscheiden sich in genau einem Bit.', v: { type: 'heap', size: 64, title: 'Buddy-Allokator: malloc(7 KB)', frames: [{ note: 'Start: 64 KB', blocks: [['', 64]] }, { note: 'Halbieren: 32 + 32', blocks: [['', 32], ['', 32]] }, { note: 'Halbieren: 16 + 16 + 32', blocks: [['', 16], ['', 16], ['', 32]] }, { note: '8 KB vergeben (1 KB intern verschwendet)', blocks: [['A', 8], ['', 8], ['', 16], ['', 32]] }] } }
  ];

